\begin{equation}
\label{equation-compose-counits}
\epsilon_X^v \circ u(\epsilon^{v'}_{v(X)}) = \epsilon^{v''}_X :
u''(v''(X)) \to X
\end{equation}
Where $\epsilon$ is the counit of the adjunctions.
\end{enumerate}

